import { API, graphqlOperation } from "aws-amplify";
export default {
  components: {
    AssetCategorieslist,
    AssetSuppliersList,
    AddSuppliers,
    AddCategories,
    AllAssetlist,
    CreateAsset,
    SnackBar,
    AssetRetirelist,
    AssetSubCategories,
    AddSubcategories,
    AddRetirereason,
    QRGenearation,
    AssetLocations,
    AssetLocationCreation,
    AssetSettings,
    AseetReports,
    AssetVerification,
    RetairedAsset,
    ProcurmentDialog,
    AllRequestedAssets,
    AssetsIntransit,
    AssetsInWarehouse,
    UserRequestAsset,
    UserAsset,
    BulkAsset,
    UploadAsset,
    ExportAssetReportsDialog
  },
  mixins: [get_all_org_users],
  data: () => ({
    toggle_exclusive: "userassets",
    supplierAddition: false,
    categoriesAddition: false,
    retireAddition: false,
    assetCreation: false,
    categoriessubAddition: false,
    componentCheck: 0,
    categoryKey: 0,
    SnackBarComponent: {},
    supplierKey: 0,
    subkeycategory: 0,
    assetkey: 0,
    retireKey: 0,
    addAssetLocationDialog: false,
    requestDialog: true,
    locRefresh: 0,
    loading: false,
    assetProcureDialog: false,
    adminAppExists: false,
    windowHeight: 0,
    showFilterDrawer: false,
    goLoading: false,
    // Filter properties
    userselect: "ALL",
    assettaggedstatus: "ALL",
    categoriesName: "ALL",
    categoriessubName: "ALL",
    userArray: [],
    assetitemstagged: [{
      title: "All",
      value: "ALL"
